window.MG_LAZY_DATA["data/lazy/resources/security-v26-047-ca4027b1481c9f0f.json"]={sha256:"ca4027b1481c9f0fba5cee0bffd0d89fd818213e09c312af12ba5dc641570958",value:{"sources":[{"id":"v26-case-aca8ed3696682883","url":"https://source.android.com/docs/security/features/verifiedboot","title":"Android Verified Boot","titleEn":"Android Verified Boot","publisher":"Android Open Source Project","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-047","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-047","related":[{"id":"security-v26-048","referenceUrls":["https://www.trustedcomputinggroup.org/resources/documents/tpm-library-specification"],"title":"TPM 2.0：PCR量測、Quote 與新鮮度","titleEn":"TPM 2.0: PCR measurements, quotes and freshness","why":"用兩課的可觀察驗收條件比較模型邊界：3與1僅為索引差，簽章錯誤及過舊索引均拒絕；教材無解鎖、繞過或刷入第三方裝置的步驟。 交付驗證鏈圖、三類負/正例及索引比較表。","whyEn":"Compare model boundaries using observable acceptance criteria: Treat 3 and 1 only as index gaps and reject invalid signatures or old indices; no unlocking, bypass or third-party flashing steps are included. Deliver the verification-chain diagram, three validation cases and index comparisons.","difference":"用合成開機事件序列示範PCR延伸H(舊PCR||事件digest)；列出quote簽章、選取PCR、nonce及event log各自驗證責任。","differenceEn":"Use a synthetic boot-event sequence to illustrate PCR extension H(old PCR||event digest); separate quote signature, selected PCRs, nonce and event-log checks.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["教學回滾判定要求候選index≥已記錄最低index，且簽章與其他驗證通過；差值是索引間距，不是安全強度或版本年齡。 已儲存最低index=7，候選index=10；兩者均為同一rollback位置的整數。 候選高出10−7=3個索引單位；候選改8時高出1個；候選6則應拒絕。","若選取n個SHA-256 PCR值，原始digest資料量=32n位元組；不含簽章、選擇位圖與quote其他結構，量測不同不直接等於惡意。 教學挑選8個PCR，每個digest32位元組，僅計原始選取值。 8×32=256位元組；挑選12個後為384位元組。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["The teaching rollback rule requires candidate index≥stored minimum plus valid signatures and other checks; index difference is neither strength nor version age. Stored minimum index is 7 and candidate is 10, both integers for the same rollback location. Candidate margin is 10−7=3 index units; candidate 8 gives one, while candidate 6 must be rejected.","Selecting n SHA-256 PCR values yields 32n raw digest bytes, excluding signature, selection bitmap and other quote structures; differing measurements do not automatically imply malice. Select eight teaching PCRs with 32-byte digests and count only raw selected values. 8×32=256 bytes; selecting 12 gives 384 bytes.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-057","referenceUrls":["https://spdx.dev/use/specifications/"],"title":"SPDX：元件關係圖與SBOM完整性","titleEn":"SPDX: relationship graphs and SBOM completeness","why":"用兩課的可觀察驗收條件比較模型邊界：3與1僅為索引差，簽章錯誤及過舊索引均拒絕；教材無解鎖、繞過或刷入第三方裝置的步驟。 交付驗證鏈圖、三類負/正例及索引比較表。","whyEn":"Compare model boundaries using observable acceptance criteria: Treat 3 and 1 only as index gaps and reject invalid signatures or old indices; no unlocking, bypass or third-party flashing steps are included. Deliver the verification-chain diagram, three validation cases and index comparisons.","difference":"區分檔案、套件、文件與關係識別碼，檢查每條關係端點是否存在並追到發布主體。","differenceEn":"Distinguish files, packages, documents and relationship identifiers; validate endpoints and trace each component to the release subject.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["教學回滾判定要求候選index≥已記錄最低index，且簽章與其他驗證通過；差值是索引間距，不是安全強度或版本年齡。 已儲存最低index=7，候選index=10；兩者均為同一rollback位置的整數。 候選高出10−7=3個索引單位；候選改8時高出1個；候選6則應拒絕。","圖完整性=端點均可解析的關係數/全部關係；欄位存在不保證內容真實。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成SBOM有25個元件與30條關係，3條引用不存在的元件。 可解析關係27/30=90%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["The teaching rollback rule requires candidate index≥stored minimum plus valid signatures and other checks; index difference is neither strength nor version age. Stored minimum index is 7 and candidate is 10, both integers for the same rollback location. Candidate margin is 10−7=3 index units; candidate 8 gives one, while candidate 6 must be rejected.","Graph integrity is resolvable relationships divided by all relationships; populated fields do not prove truthful content. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. A synthetic SBOM contains twenty-five components and thirty relationships; three reference absent components. Resolvable relationship fraction=27/30=90%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-bb25785c3cf8abf7","url":"https://www.trustedcomputinggroup.org/resources/documents/tpm-library-specification","title":"TPM 2.0 Library specification","titleEn":"TPM 2.0 Library specification","publisher":"Trusted Computing Group","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-f076457a5bdddea9","url":"https://spdx.dev/use/specifications/","title":"SPDX specifications","titleEn":"SPDX specifications","publisher":"SPDX","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
